{"path": "durations.py", "content": "import re

_PART = re.compile(r'([0-9]+)([hms])')
_SPACES = re.compile(r' *')
_ORDER = {'h': 0, 'm': 1, 's': 2}
_FACTOR = {'h': 3600, 'm': 60, 's': 1}


def parse_duration(text):
    """See SPEC.md."""
    if not isinstance(text, str):
        raise ValueError('duration must be a string')
    pos = 0
    total = 0
    last = -1
    while True:
        m = _PART.match(text, pos)
        if not m:
            raise ValueError(f'invalid duration: {text!r}')
        unit = m.group(2)
        if _ORDER[unit] <= last:
            raise ValueError(f'repeated or out-of-order unit in {text!r}')
        last = _ORDER[unit]
        total += int(m.group(1)) * _FACTOR[unit]
        pos = m.end()
        if pos == len(text):
            return total
        # Spaces are only allowed between parts, so another part must follow.
        pos = _SPACES.match(text, pos).end()
        if pos == len(text):
            raise ValueError(f'invalid duration: {text!r}')
"}

